<?php declare(strict_types=1); namespace Haerriz\AgenticCommerce\Model\Tool;
use Haerriz\AgenticCommerce\Model\Knowledge\KnowledgeService;
class AnswerStoreQuestion implements ToolInterface { public function __construct(private KnowledgeService $service){} public function getName():string{return 'answer_store_question';} public function getDefinition():array{return ['type'=>'function','function'=>['name'=>$this->getName(),'description'=>'Search active, current-store Magento CMS pages and blocks for grounded store policy, support, and storefront knowledge.','parameters'=>['type'=>'object','properties'=>['query'=>['type'=>'string'],'limit'=>['type'=>'integer','minimum'=>1,'maximum'=>5]],'required'=>['query']]]];} public function execute(array $arguments,array $context=[]):array{$items=$this->service->search((string)($arguments['query']??''),(int)($arguments['limit']??3));$actions=[];foreach($items as $i){$actions[]=['type'=>'navigate','label'=>(string)$i['title'],'url'=>(string)$i['url'],'auto_navigate'=>false];}$message=$items?(string)__('I found relevant store information. %1',(string)$items[0]['snippet']):(string)__('I could not find matching store information.');return ['knowledge'=>$items,'actions'=>$actions,'assistant_message'=>$message];} }
